package org.json
// In-process registry emulates JSON API; not an Android JSON parser.
private object Registry{val obj=mutableMapOf<String,Map<String,Any?>>();val arr=mutableMapOf<String,List<Any?>>()}
private fun enc(v:Any?)=v.toString().let{"${it.length}:$it"}
class JSONObject{companion object{val NULL=object{override fun toString()="null"}};private val m=linkedMapOf<String,Any?>();constructor();constructor(s:String){if(s!="{}")m.putAll(Registry.obj[s]?:error("unknown object"))};fun put(k:String,v:Any?):JSONObject{m[k]=v;return this};fun has(k:String)=m.containsKey(k);fun isNull(k:String)=m[k]==null||m[k]===NULL;fun getString(k:String)=m[k] as String;fun getLong(k:String)=m[k].toString().toLong();fun getInt(k:String)=getLong(k).toInt();fun getDouble(k:String)=m[k].toString().toDouble();fun getBoolean(k:String)=m[k] as Boolean;fun optString(k:String,d:String="")=if(isNull(k))d else m[k].toString();fun optLong(k:String,d:Long=0)=m[k]?.toString()?.toLongOrNull()?:d;fun optInt(k:String,d:Int=0)=optLong(k,d.toLong()).toInt();fun optDouble(k:String,d:Double=0.0)=m[k]?.toString()?.toDoubleOrNull()?:d;fun optBoolean(k:String,d:Boolean=false)=m[k] as? Boolean?:d;fun optJSONObject(k:String)=m[k] as? JSONObject;fun optJSONArray(k:String)=m[k] as? JSONArray;fun getJSONObject(k:String)=m[k] as JSONObject;override fun toString():String{val t="OJ:"+m.entries.joinToString("|"){enc(it.key)+enc(it.value)};Registry.obj[t]=LinkedHashMap(m);return t}}
class JSONArray{private val a=mutableListOf<Any?>();constructor();constructor(xs:Collection<*>){a.addAll(xs)};constructor(s:String){if(s!="[]")a.addAll(Registry.arr[s]?:error("unknown array"))};fun put(v:Any?):JSONArray{a.add(v);return this};fun length()=a.size;fun getJSONObject(i:Int)=a[i] as JSONObject;fun getInt(i:Int)=(a[i] as Number).toInt();fun optString(i:Int,d:String="")=a.getOrNull(i)?.toString()?:d;override fun toString():String{val t="AJ:"+a.joinToString("|"){enc(it)};Registry.arr[t]=a.toList();return t}}
